// Vista normalizada de la hoja "Indice distrital" para el panel del visor.
(function () {
    var zonaPorCategoria = {
        EXC: 'Uso Residencial Exclusivo',
        PREF: 'Uso Residencial Preferente',
        ESP: 'Uso Residencial Especial',
        VEC: 'Uso Mixto Vecinal',
        ZON: 'Uso Mixto Zonal',
        MET: 'Uso Mixto Metropolitano',
        INT: 'Uso Mixto Intensivo',
        ESPZ: 'Uso Mixto Especializado',
        REC: 'Uso de Recreación Pública',
        HOS: 'Hospitales',
        EDU: 'Educación',
        OU: 'Otros Usos'
    };

    window.datosActividadesIndice = (datosBuscadorGiros.giros || []).map(function (giro) {
        var zonas = {};
        Object.keys(giro.compatibilidad || {}).forEach(function (categoria) {
            var zona = zonaPorCategoria[categoria];
            if (zona) zonas[zona] = giro.compatibilidad[categoria];
        });
        var numero = String(giro.cod_giro || '').split('-').pop();
        return {
            SECCIÓN: '',
            DIVISIÓN: '',
            GRUPO: '',
            CLASE: String(giro.clase || ''),
            'N°': numero.replace(/^0+/, '') || '0',
            ACTIVIDAD: giro.giro || '',
            ZONAS: zonas,
            OBSERVACIONES: '',
            COD_GIRO: giro.cod_giro || '',
            ESCALA: giro.escala || '',
            NOMBRES_PARA_EL_VISOR: giro.nombres_comunes || [],
            BUSQUEDA: giro.buscar || []
        };
    });
})();